<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Pomofocus</title>
<style>
*{box-sizing:border-box}
html,body{margin:0;min-height:100%;font-family:Arial,Helvetica,sans-serif;color:#fff}
body{background:#b6374a;transition:background .25s}
body.short{background:#866168}
body.long{background:#378d90}
.app{width:100%;min-height:100vh;padding:20px 18px 55px}
.topbar{height:72px;border-bottom:1px solid rgba(0,0,0,.12);display:flex;align-items:flex-start;justify-content:space-between}
.brand{font-weight:bold;font-size:30px;line-height:48px;white-space:nowrap}
.brand span{font-size:28px;margin-right:7px}
.actions{display:flex;gap:15px}
.icon-btn{border:0;border-radius:6px;background:rgba(255,255,255,.16);height:51px;width:51px;color:#fff;font-size:28px;font-weight:bold;cursor:pointer}
.icon-btn.chart{font-size:25px}
.icon-btn.gear{font-size:27px}
.icon-btn.user{font-size:28px}
.icon-btn.more{font-size:30px;line-height:20px}
.timer-box{margin-top:60px;background:rgba(255,255,255,.13);border-radius:7px;padding:30px 12px 36px;text-align:center}
.tabs{display:flex;justify-content:center;gap:7px;font-size:24px;white-space:nowrap}
.tab{padding:9px 18px;border-radius:5px;cursor:pointer}
.tab.active{background:rgba(100,20,35,.28);font-weight:bold}
.time{font-size:150px;font-weight:bold;line-height:1.08;margin:45px 0 35px;letter-spacing:-4px}
.start{width:300px;height:91px;border:0;border-radius:5px;background:#fff;box-shadow:0 9px 0 rgba(220,220,220,.65);color:#a63446;font-size:34px;font-weight:bold;cursor:pointer}
.short .start{color:#76545c}
.long .start{color:#358488}
.next{display:none;margin-left:45px;font-size:44px;vertical-align:middle;cursor:pointer}
.session{text-align:center;margin-top:34px;font-size:26px}
.session .num{display:block;color:rgba(255,255,255,.7);font-size:23px;margin-bottom:6px}
.task-section{margin-top:38px}
.task-heading{font-weight:bold;font-size:27px;display:flex;justify-content:space-between;align-items:center}
.task-heading .more{width:51px;height:51px}
.rule{height:3px;background:rgba(255,255,255,.7);margin:19px 0 28px}
.add-task{height:96px;border:3px dashed rgba(255,255,255,.35);border-radius:12px;display:flex;align-items:center;justify-content:center;font-size:26px;font-weight:bold;color:rgba(255,255,255,.72);cursor:pointer}
.add-task span{font-size:32px;margin-right:10px}
.task-row{height:93px;background:#fff;color:#4d5156;border-radius:6px;border-left:8px solid #25252a;margin-bottom:15px;display:flex;align-items:center;padding:0 20px;gap:16px;font-size:25px;font-weight:bold}
