.task-row .count{margin-left:auto;color:#999}
.row-more{height:46px;width:44px;border:1px solid #ddd;background:#fff;border-radius:6px;color:#999;font-size:25px}
.editor{background:#fff;color:#4d5156;border-radius:11px;overflow:hidden;margin-top:15px}
.editor-main{padding:35px 30px 28px}
.task-input{width:100%;height:70px;border:1px solid #e2e5eb;border-radius:6px;padding:8px 3px;font-size:33px;color:#4c5156;outline:none}
.task-input::placeholder{color:#dfe1e3;font-style:italic;font-weight:bold}
.est{font-size:25px;font-weight:bold;margin-top:25px}
.est-controls{display:flex;gap:14px;margin-top:14px}
.est-number{width:113px;height:57px;background:#eee;border-radius:8px;padding:13px 15px;font-size:24px}
.arrow{height:57px;width:57px;background:#fff;border:1px solid #ddd;border-radius:14px;box-shadow:0 2px 4px #ddd;font-size:20px;color:#777}
.links{margin-top:27px;font-size:22px;color:#999;font-weight:bold;text-decoration:underline}
.links span{margin-right:17px}
.editor-actions{height:99px;background:#f7f7f7;border-top:1px solid #eee;display:flex;justify-content:flex-end;align-items:center;gap:45px;padding:0 30px;color:#999;font-size:22px;font-weight:bold}
